import java.util.*;

class Solution {
    public int findCheapestPrice(int n, int[][] flights, int src, int dst, int k) {
        final int INF = 1_000_000_000;
        int[] cost = new int[n];
        Arrays.fill(cost, INF);
        cost[src] = 0;

        for (int flightsUsed = 0; flightsUsed <= k; flightsUsed++) {
            int[] next = Arrays.copyOf(cost, n);
            for (int[] flight : flights) {
                int from = flight[0], to = flight[1], price = flight[2];
                if (cost[from] != INF && cost[from] + price < next[to]) {
                    next[to] = cost[from] + price;
                }
            }
            cost = next;
        }

        return cost[dst] == INF ? -1 : cost[dst];
    }
}

import java.util.*;

class Solution {
    public int findCheapestPrice(int n, int[][] flights, int src, int dst, int k) {
        List<List<int[]>> graph = new ArrayList<>();
        for (int i = 0; i < n; i++) graph.add(new ArrayList<>());
        for (int[] flight : flights) {
            graph.get(flight[0]).add(new int[] {flight[1], flight[2]});
        }

        int maxFlights = k + 1;
        int[][] best = new int[n][maxFlights + 1];
        for (int[] row : best) Arrays.fill(row, Integer.MAX_VALUE);
        best[src][0] = 0;

        PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
        pq.offer(new int[] {0, src, 0});

        while (!pq.isEmpty()) {
            int[] cur = pq.poll();
            int price = cur[0], city = cur[1], flightsUsed = cur[2];
            if (city == dst) return price;
            if (flightsUsed == maxFlights || price > best[city][flightsUsed]) continue;

            for (int[] edge : graph.get(city)) {
                int nextCity = edge[0];
                int nextFlights = flightsUsed + 1;
                int nextPrice = price + edge[1];
                if (nextPrice < best[nextCity][nextFlights]) {
                    best[nextCity][nextFlights] = nextPrice;
                    pq.offer(new int[] {nextPrice, nextCity, nextFlights});
                }
            }
        }

        return -1;
    }
}

import java.util.*;

class Solution {
    public int findCheapestPrice(int n, int[][] flights, int src, int dst, int k) {
        List<List<int[]>> graph = new ArrayList<>();
        for (int i = 0; i < n; i++) graph.add(new ArrayList<>());
        for (int[] flight : flights) {
            graph.get(flight[0]).add(new int[] {flight[1], flight[2]});
        }

        int[] best = new int[n];
        Arrays.fill(best, Integer.MAX_VALUE);
        best[src] = 0;

        Queue<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[] {src, 0});

        for (int flightsUsed = 0; flightsUsed <= k && !queue.isEmpty(); flightsUsed++) {
            int size = queue.size();
            int[] layerBest = Arrays.copyOf(best, n);
            for (int i = 0; i < size; i++) {
                int[] state = queue.poll();
                int city = state[0], price = state[1];
                for (int[] edge : graph.get(city)) {
                    int nextCity = edge[0];
                    int nextPrice = price + edge[1];
                    if (nextPrice < layerBest[nextCity]) {
                        layerBest[nextCity] = nextPrice;
                        queue.offer(new int[] {nextCity, nextPrice});
                    }
                }
            }
            best = layerBest;
        }

        return best[dst] == Integer.MAX_VALUE ? -1 : best[dst];
    }
}

import java.util.*;

class Solution {
    private static final int INF = 1_000_000_000;
    private List<List<int[]>> graph;
    private int[][] memo;
    private int dst;

    public int findCheapestPrice(int n, int[][] flights, int src, int dst, int k) {
        this.dst = dst;
        graph = new ArrayList<>();
        for (int i = 0; i < n; i++) graph.add(new ArrayList<>());
        for (int[] flight : flights) {
            graph.get(flight[0]).add(new int[] {flight[1], flight[2]});
        }

        memo = new int[n][k + 2];
        for (int[] row : memo) Arrays.fill(row, -2);
        int answer = dfs(src, k + 1);
        return answer >= INF ? -1 : answer;
    }

    private int dfs(int city, int remainingFlights) {
        if (city == dst) return 0;
        if (remainingFlights == 0) return INF;
        if (memo[city][remainingFlights] != -2) return memo[city][remainingFlights];

        int best = INF;
        for (int[] edge : graph.get(city)) {
            int nextCost = dfs(edge[0], remainingFlights - 1);
            if (nextCost != INF) {
                best = Math.min(best, edge[1] + nextCost);
            }
        }
        memo[city][remainingFlights] = best;
        return best;
    }
}
